ALTER TABLE runs ADD COLUMN runtime_pending_deadline_ms INTEGER CHECK(runtime_pending_deadline_ms IS NULL OR runtime_pending_deadline_ms>=0);
ALTER TABLE documents ADD COLUMN runtime_entry_token TEXT;
ALTER TABLE documents ADD COLUMN runtime_entry_sequence INTEGER NOT NULL DEFAULT 0 CHECK(runtime_entry_sequence>=0);
CREATE TABLE runtime_interruptions(run_id TEXT NOT NULL REFERENCES runs(id),fingerprint TEXT NOT NULL,workflow_id TEXT NOT NULL,stage TEXT NOT NULL,episode_id TEXT NOT NULL UNIQUE,entry_token TEXT NOT NULL,interruptions INTEGER NOT NULL CHECK(interruptions BETWEEN 1 AND 3),state TEXT NOT NULL CHECK(state IN('pending','reentered','terminal')),first_observed_ms INTEGER NOT NULL,deadline_ms INTEGER NOT NULL,observed_ms INTEGER NOT NULL,next_check_ms INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0),lease_id TEXT,lease_until_ms INTEGER,diagnostic_json TEXT NOT NULL,observation_error_json TEXT,native_status TEXT,resolved_at TEXT,resolved_entry_token TEXT,PRIMARY KEY(run_id,fingerprint),FOREIGN KEY(run_id,fingerprint) REFERENCES documents(run_id,fingerprint),CHECK(deadline_ms=first_observed_ms+900000));
CREATE INDEX runtime_interruptions_due ON runtime_interruptions(run_id,state,next_check_ms,first_observed_ms,fingerprint);
